        if (value !== undefined) {
            searchParams.set(key, String(value))
        }
    })
    const qs = searchParams.toString()
    return qs ? `${fullPath}?${qs}` : fullPath
}

const billingFetch = async <T>(service: BillingServiceName, path: string, options: RequestOptions = {}): Promise<T> => {
    const basePath = BILLING_PROXY_PATHS[service]
    const { body, params, headers, ...restOptions } = options

    const url = buildUrl(basePath, path, params)

    const response = await fetch(url, {
