    return (
        <ScrollableTableContainer>
            <Table<DictionaryItem>
                loading={loading}
                size="small"
                rowKey="id"
                pagination={{
                    current: currentPage,
                    pageSize: pageSize,
                    total: totalCount,
                    showSizeChanger: true,
                    showTotal: (total) => `총 ${total}개`,
